Extensions.ExtractScript:
param(
    [xml] $Document
);

foreach( $file in $Document.unattend.Extensions.File ) {
    $path = [System.Environment]::ExpandEnvironmentVariables( $file.GetAttribute( 'path' ) );
    mkdir -Path( $path | Split-Path -Parent ) -ErrorAction 'SilentlyContinue';
    $encoding = switch( [System.IO.Path]::GetExtension( $path ) ) {
        { $_ -in '.ps1', '.xml' } { [System.Text.Encoding]::UTF8; }
        { $_ -in '.reg', '.vbs', '.js' } { [System.Text.UnicodeEncoding]::new( $false, $true ); }
        default { [System.Text.Encoding]::Default; }
    };
    $bytes = $encoding.GetPreamble() + $encoding.GetBytes( $file.InnerText.Trim() );
    [System.IO.File]::WriteAllBytes( $path, $bytes );
}

Extensions.File:
# Installs VMware Tools during Windows specialize, from a mounted Tools ISO or by direct download if none is attached.
[CmdletBinding()]
param(
    [Parameter(HelpMessage = "Proxy server URL to route the VMware Tools download listing and installer fetch through, for example http://proxy.example.com:8080. Omit to use the machine's default network configuration.")]
    [ValidateScript({
        $ParsedUri = $null
        if (-not [Uri]::TryCreate($_, [UriKind]::Absolute, [ref]$ParsedUri)) {
            throw "The value '$_' is not a valid absolute URI."
        }
        $true
    })]
    [string]$ProxyUrl
)

# Splatted onto every Invoke-WebRequest call so -ProxyUrl, when given, is the only place proxy routing is decided
$script:WebRequestProxyArgs = @{}
if ($ProxyUrl) {
    $script:WebRequestProxyArgs['Proxy'] = $ProxyUrl
}

& {
	# VMware's documented silent switches: /S for the bootstrapper, /v passes the rest to the MSI.
	$silent = '/S /v"/qn REBOOT=R"';

	# Preferred path: a hypervisor mounted Tools ISO, identified by a setup.exe whose product name is 'VMware Tools'.
	foreach( $letter in 'DEFGHIJKLMNOPQRSTUVWXYZ'.ToCharArray() ) {
		$exe = "${letter}:\setup.exe";
		if( ( Get-Item -LiteralPath $exe -ErrorAction 'SilentlyContinue' | Select-Object -ExpandProperty 'VersionInfo' | Select-Object -ExpandProperty 'ProductName' ) -eq 'VMware Tools' ) {
			'Installing VMware Tools from {0}.' -f $exe;
			Start-Process -FilePath $exe -ArgumentList $silent -Wait;
			return;
		}
	}
	'VMware Tools image (windows.iso) is not attached to this VM. Falling back to a direct download.';

	# The drive scan also comes up empty on physical hardware, so confirm this really is a VM before downloading anything.
	if( ( Get-CimInstance -ClassName 'Win32_ComputerSystem' ).Manufacturer -notmatch 'VMware' ) {
		'This is not a VMware virtual machine, so nothing will be downloaded.';
		return;
	}

	$base = 'https://packages.vmware.com/tools/releases/latest/windows/x64/';
	[System.Net.ServicePointManager]::SecurityProtocol = [System.Net.SecurityProtocolType]::Tls12;
	$ProgressPreference = 'SilentlyContinue';

	# First logon can start before DHCP settles, so keep retrying the listing for about three minutes.
	$name = $null;
	for( $i = 1; $i -le 18 -and -not $name; $i++ ) {
		try {
			$name = @( ( Invoke-WebRequest -Uri $base -UseBasicParsing -TimeoutSec 15 @script:WebRequestProxyArgs ).Links.href | Where-Object { $_ -like '*.exe' -and $_ -notmatch '[\\/:]' } )[0];
		}
		catch {
			'Attempt {0} to read {1} failed: {2}' -f $i, $base, $_.Exception.Message;
		}
		if( -not $name ) {
			Start-Sleep -Seconds 10;
		}
	}
	if( -not $name ) {
		'Could not reach the VMware download site. VMware Tools was not installed.';
		return;
	}

	$file = Join-Path -Path $env:TEMP -ChildPath $name;
	try {
		'Downloading {0}.' -f $name;
		Invoke-WebRequest -Uri ( $base + $name ) -OutFile $file -UseBasicParsing @script:WebRequestProxyArgs;
		# Never execute the download unless Authenticode says it is intact and signed by VMware/Broadcom.
		$sig = Get-AuthenticodeSignature -LiteralPath $file;
		if( $sig.Status -ne 'Valid' -or $sig.SignerCertificate.Subject -notmatch 'VMware|Broadcom' ) {
			'Refusing to run {0}: signature status is {1}, signer is {2}.' -f $name, $sig.Status, $sig.SignerCertificate.Subject;
			return;
		}
		'Installing {0}.' -f $name;
		Start-Process -FilePath $file -ArgumentList $silent -Wait;
	}
	catch {
		'Download or installation failed: {0}' -f $_.Exception.Message;
	}
	finally {
		Remove-Item -LiteralPath $file -Force -ErrorAction 'SilentlyContinue';
	}
} *>&1 | Out-String -Width 1KB -Stream >> 'C:\Windows\Setup\Scripts\VMwareTools.log';

# Matched on SMBIOS identity rather than HypervisorPresent, which is also true on physical hosts running Hyper-V or VBS.
$cs = Get-CimInstance -ClassName 'Win32_ComputerSystem';
$isVirtualMachine = "$($cs.Manufacturer) $($cs.Model)" -match 'virtual|vmware|vbox|kvm|qemu|xen|bochs|parallels';

$scripts = @(
	{
		# Allow file paths longer than 260 characters.
		reg.exe add "HKLM\SYSTEM\CurrentControlSet\Control\FileSystem" /v LongPathsEnabled /t REG_DWORD /d 1 /f
	};
	{
		# Enable Remote Desktop: open the RDP firewall rule group and stop denying terminal server connections.
		netsh.exe advfirewall firewall set rule group="@FirewallAPI.dll,-28752" new enable=Yes;
		reg.exe add "HKLM\SYSTEM\CurrentControlSet\Control\Terminal Server" /v fDenyTSConnections /t REG_DWORD /d 0 /f;
	};
	{
		# Allow locally written PowerShell scripts to run, while downloaded ones still need a signature.
		Set-ExecutionPolicy -Scope 'LocalMachine' -ExecutionPolicy 'RemoteSigned' -Force;
	};
	{
		# Stop NTFS from updating last access timestamps, a small disk performance win.
		fsutil.exe behavior set disableLastAccess 1;
	};
	{
		# Reclaims a hiberfil.sys the size of installed RAM, and turns off Fast Startup with it.
		powercfg.exe /hibernate off;
	};
	{
		# A VM that sleeps or blanks mid task is only friction, while physical machines sleep normally.
		if( $isVirtualMachine ) {
			powercfg.exe /setactive SCHEME_MIN;
			powercfg.exe /change standby-timeout-ac 0;
			powercfg.exe /change monitor-timeout-ac 0;
			powercfg.exe /change disk-timeout-ac 0;
		}
		else {
			# Reset rather than skip: a gold image built on a reference VM bakes never-sleep timeouts into
			# the capture, and a laptop deployed from it would otherwise never suspend. Safe on a fresh
			# install, where nothing has customized power yet, but it does reactivate Balanced.
			powercfg.exe /restoredefaultschemes;
		}
	};
	{
		# MODIFIED (change 2): VMs skip automatic BitLocker device encryption, because encrypted guests defeat
		# block level deduplication on the SAN. Physical machines encrypt as normal.
		if( $isVirtualMachine ) {
			reg.exe add "HKLM\SYSTEM\CurrentControlSet\Control\BitLocker" /v "PreventDeviceEncryption" /t REG_DWORD /d 1 /f;
		}
		else {
			# Removed, not just left alone: a gold image sets this during its build to protect the capture, so
			# a physical machine deployed from one would inherit it and silently never encrypt.
			Remove-ItemProperty -LiteralPath 'Registry::HKLM\SYSTEM\CurrentControlSet\Control\BitLocker' -Name 'PreventDeviceEncryption' -Force -ErrorAction 'SilentlyContinue';
			'Physical machine ({0} {1}), automatic device encryption left enabled.' -f $cs.Manufacturer, $cs.Model;
		}

		# Set unconditionally, and before any volume is encrypted, so BitLocker uses AES 256 whenever it does run
		# (automatic device encryption on a physical machine, or someone enabling it by hand later).
		# 7 = XTS-AES 256 for the OS and fixed data drives, while removable drives get 4 (AES-CBC 256), which older Windows can still read.
		reg.exe add "HKLM\SOFTWARE\Policies\Microsoft\FVE" /v EncryptionMethodWithXtsOs /t REG_DWORD /d 7 /f;
		reg.exe add "HKLM\SOFTWARE\Policies\Microsoft\FVE" /v EncryptionMethodWithXtsFdv /t REG_DWORD /d 7 /f;
		reg.exe add "HKLM\SOFTWARE\Policies\Microsoft\FVE" /v EncryptionMethodWithXtsRdv /t REG_DWORD /d 4 /f;
	};
	{
		# Skip Microsoft Edge's first run / welcome experience.
		reg.exe add "HKLM\Software\Policies\Microsoft\Edge" /v HideFirstRunExperience /t REG_DWORD /d 1 /f;
	};
	{
		# MODIFIED (change 6): dispatch driver install by manufacturer. Runs during specialize, before any
		# interactive session exists, so there is no desktop to show a window on and the calls are synchronous.
		$manufacturer = ( Get-CimInstance -ClassName 'Win32_ComputerSystem' ).Manufacturer;
		if( $manufacturer -match 'Dell' ) {
			& 'C:\Windows\Setup\Scripts\Install-DellDrivers.ps1';
		}
		elseif( $manufacturer -match 'Microsoft' ) {
			& 'C:\Windows\Setup\Scripts\Install-SurfaceDrivers.ps1';
		}
		else {
			'Manufacturer {0} matched neither Dell nor Microsoft/Surface; no driver script was launched.' -f $manufacturer;
		}
	};
	{
		# Install VMware Tools from the mounted ISO or by download.
		& 'C:\Windows\Setup\Scripts\VMwareTools.ps1';
	};
	{
		# Remove the leftover previous installation folder.
		cmd.exe /c "rmdir C:\Windows.old";
	};
	{
		# Delete the answer files, which contain no secrets now but should not linger on disk.
		Remove-Item -LiteralPath @(
		  'C:\Windows\Panther\unattend.xml';
		  'C:\Windows\Panther\unattend-original.xml';
		  'C:\Windows\Setup\Scripts\Wifi.xml';
		) -Force -ErrorAction 'SilentlyContinue' -Verbose;
	};
);

# Runner: shows a progress bar, executes each block in order, and appends timing plus all output streams to the log.
& {
  [float] $complete = 0;
  [float] $increment = 100 / $scripts.Count;
  foreach( $script in $scripts ) {
    Write-Progress -Id 0 -Activity 'Running scripts to customize your Windows installation. Do not close this window.' -PercentComplete $complete;
    '*** Will now execute command «{0}».' -f $(
      $script.ToString().Trim() -replace '\s+', ' ' -replace '^(.{99})(.+)$', '$1…';
    );
    $start = [datetime]::Now;
    & $script;
    '*** Finished executing command after {0:0} ms.' -f [datetime]::Now.Subtract( $start ).TotalMilliseconds;
    "`r`n" * 3;
    $complete += $increment;
  }
} *>&1 | Out-String -Width 1KB -Stream >> "C:\Windows\Setup\Scripts\Specialize.log";
